[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$SessionRoot)
$ErrorActionPreference='Stop';$temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath());$session=[IO.Path]::GetFullPath($SessionRoot);if(-not$session.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)-or(Split-Path $session -Leaf)-notmatch '^dual-pool-u006-primary-[a-f0-9]{32}$'){throw 'UNSAFE_SESSION_ROOT'}
$state=Join-Path $session 'state/recovery-marker.json';$backup=Join-Path $session 'backup/config.toml';$config=Join-Path $env:USERPROFILE '.codex/config.toml';if(-not(Test-Path $state)){throw 'RECOVERY_MARKER_ABSENT'};$marker=Get-Content -Raw $state|ConvertFrom-Json;if($marker.restore_required -ne $true){throw 'RECOVERY_NOT_REQUIRED'};if(-not(Test-Path $backup)){throw 'RECOVERY_BACKUP_ABSENT'};$stage=Join-Path (Split-Path $config) ('.dualpool-restore-'+[guid]::NewGuid().ToString('N')+'.tmp');$replaceBackup=$stage+'.replace-backup';Copy-Item -LiteralPath $backup -Destination $stage -Force;if(Test-Path $config){[IO.File]::Replace($stage,$config,$replaceBackup,$true);if(Test-Path $replaceBackup){Remove-Item -LiteralPath $replaceBackup -Force}}else{Move-Item -LiteralPath $stage -Destination $config -Force};if((Get-FileHash $config -Algorithm SHA256).Hash -ne $marker.original_sha256){throw 'CONFIG_RESTORE_MISMATCH'};Remove-Item -LiteralPath $state -Force;[pscustomobject]@{status='PASS';restore_verified=$true;auth_material_inspected=$false}
